// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.cognitive.solverimport com.roshan.persona.cognitive.model.Constraintimport com.roshan.persona.cognitive.model.SolutionApproachimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.withContext/** * NOUS — Pattern Matcher (Module 7 v2 — Step 7.6). * * Recalls past solutions from Module 3 (Memory) + analogical reasoning. * * ## What it does * * 1. **Pattern matching** — when the user asks a question, recall similar *    past problems from Memory. If a similar problem was solved before, *    adapt the previous solution. * *    Example: "How do I fix my router?" → recall "user fixed router last *    month by restarting it" → suggest restart first. * * 2. **Analogical reasoning** — find a structurally similar problem in a *    different domain and apply the solution pattern. * *    Example: "How to organize a wedding?" → analogous to "how to organize *    a conference" (both are event planning). * * 3. **Creative synthesis** — combine disparate ideas from different domains *    to create a novel solution. * *    Example: "How to save money on groceries?" → combine "bulk buying" + *    "seasonal shopping" + "meal prep" = "Seasonal bulk meal-prep system." * * ## v1 approach * * For v1, pattern matching uses [MemoryRecallInterface] (injected from * Module 3). Analogical + creative use LLM ([SolverLlm] interface). * Tests inject fakes for both. * * @see <a href="docs/strategy/module-7-cognitive-strategy-v2.md">§ProblemSolver</a> */class PatternMatcher(    private val memory: MemoryRecallInterface,    private val llm: SolverLlm,    private val dispatcher: CoroutineDispatcher,) {    /**     * Try to find a matching past solution from Memory.     *     * @param problem the user's problem.     * @return a [PatternMatchResult] if a match is found, or null.     */    suspend fun matchPattern(problem: String): PatternMatchResult? = withContext(dispatcher) {        val memories = try {            memory.recall(problem, k = 5)        } catch (t: Throwable) {            return@withContext null        }        if (memories.isEmpty()) return@withContext null        // Find the most relevant memory.        val bestMatch = memories.first()        return@withContext PatternMatchResult(            approach = SolutionApproach.PATTERN_MATCH,            recalledMemory = bestMatch.content,            adaptedSolution = "Based on your previous experience: ${bestMatch.content}",            confidence = 0.7f,        )    }    /**     * Try analogical reasoning — find a similar problem in a different domain.     *     * @param problem the user's problem.     * @return an [AnalogicalResult] if an analogy is found, or null.     */    suspend fun findAnalogy(problem: String): AnalogicalResult? = withContext(dispatcher) {        val prompt = """Find a structurally similar problem in a DIFFERENT domain for the following.Return the analogous problem + how its solution applies.Problem: $problemFormat:ANALOGY: [analogous problem]SOLUTION: [how the analogous solution applies to the original problem]        """.trimIndent()        val response = try {            llm.solve(prompt)        } catch (t: Throwable) {            return@withContext null        }        parseAnalogyResponse(response)    }    /**     * Try creative synthesis — combine disparate ideas to create a novel solution.     *     * @param problem the user's problem.     * @param context additional context.     * @return a [CreativeResult] with the novel solution, or null.     */    suspend fun synthesize(problem: String, context: String = ""): CreativeResult? = withContext(dispatcher) {        val prompt = """Create a NOVEL solution by combining ideas from different domains.Think outside the box — combine unexpected approaches.Problem: $problemContext: $contextReturn your creative solution in 2-3 sentences.        """.trimIndent()        val response = try {            llm.solve(prompt)        } catch (t: Throwable) {            return@withContext null        }        if (response.isBlank()) return@withContext null        CreativeResult(            approach = SolutionApproach.CREATIVE,            solution = response.trim(),            confidence = 0.6f,  // creative solutions are inherently less certain        )    }    internal fun parseAnalogyResponse(response: String): AnalogicalResult? {        if (response.isBlank()) return null        val analogy = extractField(response, "ANALOGY")        val solution = extractField(response, "SOLUTION")        if (analogy.isBlank() || solution.isBlank()) return null        return AnalogicalResult(            approach = SolutionApproach.ANALOGY,            analogousProblem = analogy,            adaptedSolution = solution,            confidence = 0.65f,        )    }    private fun extractField(text: String, fieldName: String): String {        val regex = Regex("$fieldName:\\s*(.+)", RegexOption.IGNORE_CASE)        return regex.find(text)?.groupValues?.getOrNull(1)?.trim() ?: ""    }}// ──────────────────────────────────────────────────────────────────────────/** Result of a pattern match from Memory. */data class PatternMatchResult(    val approach: SolutionApproach,    val recalledMemory: String,    val adaptedSolution: String,    val confidence: Float,)/** Result of analogical reasoning. */data class AnalogicalResult(    val approach: SolutionApproach,    val analogousProblem: String,    val adaptedSolution: String,    val confidence: Float,)/** Result of creative synthesis. */data class CreativeResult(    val approach: SolutionApproach,    val solution: String,    val confidence: Float,)// ──────────────────────────────────────────────────────────────────────────/** * Memory recall interface (injected from Module 3). * * Real implementation wraps Module 3's [com.roshan.persona.memory.MemoryInterface]. * Tests inject a fake. */interface MemoryRecallInterface {    suspend fun recall(query: String, k: Int): List<RecalledMemory>}/** One recalled memory from Module 3. */data class RecalledMemory(    val content: String,    val relevanceScore: Float = 0.5f,    val timestamp: Long = 0,)/** * LLM interface for problem solving (analogical + creative). * * Real implementation wires to Module 4. Tests inject a fake. */fun interface SolverLlm {    suspend fun solve(prompt: String): String}